// Canvas 2D placeholder face renderer (vector shapes) — reads only the flat param object.
// GENERATED by scripts/sync-skill.mjs from prototype/render.js.
// Coordinates are head-bone space: origin at the neck joint, y down, face toward +x (3/4 view).
// pal = { line, skinShade, iris, irisDark, mouth, tongue, blush }.
const TAU = Math.PI * 2;
function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}
function fillStroke(ctx, fill, line, width = 1.6) {
  ctx.fillStyle = fill;
  ctx.fill();
  ctx.lineWidth = width;
  ctx.strokeStyle = line;
  ctx.lineJoin = 'round';
  ctx.stroke();
}

// ---------------------------------------------------------------- face

const EYES = {
  L: { cx: -2.5, cy: -14.5, k: 0.8, outer: -1 },
  R: { cx: 10.5, cy: -14.5, k: 1, outer: 1 },
};

function drawEye(ctx, P, side, pal) {
  const e = EYES[side];
  const open = P[`eyeOpen${side}`];
  const smile = P[`eyeSmile${side}`];
  const w = 4.4 * e.k;
  const h = 5.6;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = pal.line;
  if (P.eyeShut > 0.5) {
    // > <  squeezed shut; chevrons point toward the nose
    const dir = side === 'R' ? -1 : 1;
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(e.cx - dir * w, e.cy - 4);
    ctx.lineTo(e.cx + dir * w * 0.8, e.cy);
    ctx.lineTo(e.cx - dir * w, e.cy + 4);
    ctx.stroke();
    return;
  }
  const eff = open * (1 - smile * 0.6);
  if (eff < 0.14) {
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    if (smile > 0.35) {
      ctx.moveTo(e.cx - w, e.cy + 1.5);
      ctx.quadraticCurveTo(e.cx, e.cy - 5, e.cx + w, e.cy + 1.5);
    } else {
      ctx.moveTo(e.cx - w, e.cy + 1);
      ctx.quadraticCurveTo(e.cx, e.cy + 3.5, e.cx + w, e.cy + 1);
    }
    ctx.stroke();
    return;
  }
  const bottom = e.cy + h - smile * h * 0.9;
  const top = bottom - 2 * h * Math.min(eff, 1.3);
  const midY = (top + bottom) / 2;
  const ry = (bottom - top) / 2;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(e.cx, midY, w, ry, 0, 0, TAU);
  ctx.fillStyle = '#fffaf7';
  ctx.fill();
  ctx.clip();
  // lid shadow
  ctx.fillStyle = 'rgba(120,100,170,0.25)';
  ctx.fillRect(e.cx - w, top, w * 2, 2.2);
  // iris + pupil
  const size = P.pupilSize;
  const ix = e.cx + P.pupilX * w * 0.5;
  const iy = e.cy + 0.6 + P.pupilY * h * 0.35;
  const irx = 3.4 * e.k * (0.72 + 0.28 * size);
  const iry = 4.8 * (0.72 + 0.28 * size);
  const g = ctx.createLinearGradient(0, iy - iry, 0, iy + iry);
  g.addColorStop(0, pal.irisDark);
  g.addColorStop(0.55, pal.iris);
  g.addColorStop(1, '#ffd27a');
  ctx.beginPath();
  ctx.ellipse(ix, iy, irx, iry, 0, 0, TAU);
  ctx.fillStyle = g;
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(ix, iy - 0.4, 1.6 * e.k * size, 2.4 * size, 0, 0, TAU);
  ctx.fillStyle = '#2a1206';
  ctx.fill();
  // highlights (fixed light from upper-right reads as "alive")
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(ix + 1.3 * e.k, iy - 2.2, 1.5, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(ix - 1.2 * e.k, iy + 2.3, 0.75, 0, TAU);
  ctx.fill();
  if (P.sparkle > 0.05) {
    ctx.globalAlpha = P.sparkle;
    star(ctx, ix - 0.4, iy + 0.4, 3 * e.k, '#fff');
    ctx.globalAlpha = 1;
  }
  ctx.restore();
  // upper lash line with a wing at the outer corner
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.ellipse(e.cx, midY, w + 0.3, ry + 0.3, 0, Math.PI * 1.06, Math.PI * 1.94);
  ctx.stroke();
  ctx.beginPath();
  const ox = e.cx + e.outer * (w + 0.2);
  ctx.moveTo(ox - e.outer * 1.2, midY - ry * 0.55);
  ctx.lineTo(ox + e.outer * 2.2, midY - ry * 0.75 - 1);
  ctx.lineWidth = 1.8;
  ctx.stroke();
  // lower lash
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.6;
  ctx.beginPath();
  ctx.ellipse(e.cx, midY, w * 0.9, ry, 0, Math.PI * 0.3, Math.PI * 0.7);
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function star(ctx, x, y, r, color) {
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.32;
    ctx.lineTo(x + Math.cos(a) * rr, y + Math.sin(a) * rr);
  }
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
}

function drawMouth(ctx, P, pal) {
  const mx = 6.5;
  const my = -5.2;
  const hw = 3.6 * P.mouthWidth;
  const curve = P.mouthCurve;
  const lY = my - curve * 1.8 + P.mouthSmirk * 0.6;
  const rY = my - curve * 1.8 - P.mouthSmirk * 2.2;
  const lx = mx - hw;
  const rx = mx + hw + P.mouthSmirk * 0.8;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = pal.line;
  if (P.mouthOpen < 0.06) {
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(lx, lY);
    ctx.quadraticCurveTo(mx, my + curve * 2.6, rx, rY);
    ctx.stroke();
    return;
  }
  const o = P.mouthOpen;
  const topY = my + curve * 1.2 - o * 0.8;
  const botY = my + curve * 2.4 + o * 8.5;
  const path = () => {
    ctx.beginPath();
    ctx.moveTo(lx, lY);
    ctx.quadraticCurveTo(mx, topY, rx, rY);
    ctx.quadraticCurveTo(mx, botY, lx, lY);
    ctx.closePath();
  };
  path();
  ctx.fillStyle = pal.mouth;
  ctx.fill();
  ctx.save();
  path();
  ctx.clip();
  ctx.beginPath();
  ctx.ellipse(mx + 0.5, botY - 0.5, hw * 0.7, Math.max(1.2, o * 3.2), 0, 0, TAU);
  ctx.fillStyle = pal.tongue;
  ctx.fill();
  if (curve > 0.4 && o > 0.25) {
    // upper teeth strip for big grins
    ctx.fillStyle = '#fff';
    ctx.fillRect(lx, topY - 2, hw * 2.2, 2.6 + o);
  }
  ctx.restore();
  path();
  ctx.lineWidth = 1.4;
  ctx.stroke();
}

/**
 * Feature parallax across the head volume. fx.yaw in -1..1 (+ = toward profile),
 * fx.pitch in -1..1 (+ = looking down), fx.eyeScale. Each feature slides by its
 * depth on the head (nose most, ear opposite) and the far eye narrows when the
 * head turns toward profile. With fx = {} every offset is 0 (original drawing).
 */
// Depths follow x = sin(angle) on a head-sized circle in 3/4 view: the far eye sits
// near the turning centre and slides the most, the near eye sits on the silhouette
// edge and barely moves, the ear (behind the cheek) slides the same way.
const FEATURE_DEPTH = { eyeL: 4, eyeR: 1.6, nose: 3, mouth: 3, browL: 4, browR: 1.6, ear: 2.4 };
function featureAt(ctx, fx, depth, cx, cy, sx = 1) {
  const yaw = fx.yaw || 0;
  const pitch = fx.pitch || 0;
  const k = fx.eyeScale || 1;
  ctx.translate(yaw * depth + cx, pitch * 1.6 + cy);
  if (sx !== 1 || k !== 1) ctx.scale(sx * k, k);
  ctx.translate(-cx, -cy);
}

function drawFaceLower(ctx, P, pal, time, fx = {}) {
  // blush under everything else
  if (P.blush > 0.02) {
    const by = fx.yaw ? fx.yaw * 2.8 : 0;
    for (const [x0, y, s] of [[14, -7.5, 1], [-4.5, -7.5, 0.8]]) {
      const x = x0 + by;
      ctx.globalAlpha = 0.5 * P.blush;
      ctx.beginPath();
      ctx.ellipse(x, y, 4.2 * s, 2.3, 0, 0, TAU);
      ctx.fillStyle = pal.blush;
      ctx.fill();
      if (P.blush > 0.3) {
        ctx.globalAlpha = Math.min(1, P.blush) * 0.8;
        ctx.strokeStyle = '#e8506f';
        ctx.lineWidth = 0.8;
        for (let i = -1; i <= 1; i++) {
          ctx.beginPath();
          ctx.moveTo(x + i * 2 * s - 0.8, y + 1.3);
          ctx.lineTo(x + i * 2 * s + 0.8, y - 1.3);
          ctx.stroke();
        }
      }
    }
    ctx.globalAlpha = 1;
  }
  const yaw = fx.yaw || 0;
  ctx.save();
  featureAt(ctx, fx, FEATURE_DEPTH.eyeL, EYES.L.cx, EYES.L.cy, 1 - 0.28 * Math.max(0, yaw) + 0.12 * Math.max(0, -yaw));
  drawEye(ctx, P, 'L', pal);
  ctx.restore();
  ctx.save();
  featureAt(ctx, fx, FEATURE_DEPTH.eyeR, EYES.R.cx, EYES.R.cy, 1 + 0.08 * Math.max(0, yaw) - 0.06 * Math.max(0, -yaw));
  drawEye(ctx, P, 'R', pal);
  ctx.restore();
  // tiny nose
  ctx.save();
  featureAt(ctx, { ...fx, eyeScale: 1 }, FEATURE_DEPTH.nose, 17, -10);
  ctx.beginPath();
  ctx.moveTo(16.5, -10.5);
  ctx.lineTo(17.4, -9.2);
  ctx.strokeStyle = pal.skinShade;
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.restore();
  ctx.save();
  featureAt(ctx, { ...fx, eyeScale: 1 + ((fx.eyeScale || 1) - 1) * 0.4 }, FEATURE_DEPTH.mouth, 6.5, -5.2);
  drawMouth(ctx, P, pal);
  ctx.restore();
  if (P.tears > 0.05) {
    ctx.globalAlpha = clamp(P.tears, 0, 1);
    ctx.strokeStyle = '#7cc8ff';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    for (const x0 of [10.5, -2.5]) {
      const x = x0 + (fx.yaw || 0) * 2.8;
      ctx.beginPath();
      ctx.moveTo(x, -9.5);
      ctx.quadraticCurveTo(x + 1, -6, x + 0.5, -9.5 + 7 * P.tears);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }
}

function drawFaceUpper(ctx, P, pal, time, fx = {}) {
  // brows drawn OVER the bangs (classic anime readability trick)
  for (const side of ['L', 'R']) {
    const e = EYES[side];
    const a = P[`browAngle${side}`];
    const by = e.cy - 9.5 * (fx.eyeScale || 1) - P.browHeight * 3.2 + (fx.pitch || 0) * 1.6;
    const inner = -e.outer;
    const half = 3.8 * e.k;
    const shift = (fx.yaw || 0) * FEATURE_DEPTH[`brow${side}`];
    const ks = fx.eyeScale || 1;
    const ix = e.cx + inner * half * ks + shift;
    const ox = e.cx - inner * half * ks + shift;
    const iy = by + a * 2.4;
    const oy = by - a * 1.2;
    ctx.beginPath();
    ctx.moveTo(ix, iy);
    ctx.quadraticCurveTo(e.cx + shift, by - 1.4, ox, oy);
    ctx.lineCap = 'round';
    ctx.strokeStyle = fx.browColor || '#1d1636';
    ctx.lineWidth = 2.6 * (fx.lineScale || 1);
    ctx.stroke();
  }
  if (P.sparkle > 0.4) {
    // "kira" glint next to the head
    const tw = 0.8 + Math.sin(time * 12) * 0.2;
    ctx.globalAlpha = (P.sparkle - 0.4) / 0.6;
    star(ctx, 25, -38, 5.5 * tw, '#ffd34d');
    star(ctx, 25, -38, 3 * tw, '#fff');
    ctx.globalAlpha = 1;
  }
  if (P.gloom > 0.05) {
    ctx.globalAlpha = 0.6 * P.gloom;
    ctx.strokeStyle = '#6a5acd';
    ctx.lineWidth = 1;
    for (let i = 0; i < 5; i++) {
      const x = -1 + i * 3.5;
      ctx.beginPath();
      ctx.moveTo(x, -34);
      ctx.lineTo(x, -34 + 8 + (i % 2) * 3);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }
  if (P.sweat > 0.05) {
    const s = P.sweat;
    const bob = Math.sin(time * 6) * 0.6;
    ctx.save();
    ctx.translate(22, -30 + bob + (1 - s) * 3);
    ctx.scale(0.8 + 0.3 * s, 0.8 + 0.3 * s);
    ctx.globalAlpha = Math.min(1, s * 1.3);
    ctx.beginPath();
    ctx.moveTo(0, -6);
    ctx.quadraticCurveTo(4, 0, 0, 3.5);
    ctx.quadraticCurveTo(-4, 0, 0, -6);
    fillStroke(ctx, '#bfe6ff', '#3d7fc4', 1.2);
    ctx.beginPath();
    ctx.arc(-1, 0.5, 0.9, 0, TAU);
    ctx.fillStyle = '#fff';
    ctx.fill();
    ctx.restore();
  }
  if (P.angerMark > 0.05) {
    const s = P.angerMark * (1 + Math.sin(time * 10) * 0.08);
    ctx.save();
    ctx.translate(15, -36);
    ctx.scale(s, s);
    ctx.strokeStyle = '#e8283a';
    ctx.lineWidth = 1.8;
    ctx.lineCap = 'round';
    for (let i = 0; i < 4; i++) {
      ctx.rotate(Math.PI / 2);
      ctx.beginPath();
      ctx.arc(3.2, 3.2, 2.6, Math.PI * 1.0, Math.PI * 1.5);
      ctx.stroke();
    }
    ctx.restore();
  }
}

export { drawFaceLower, drawFaceUpper, drawEye, drawMouth, FEATURE_DEPTH };
